export interface GetActiveAttackStatusParams {
  projectId: string;
  since?: number;
  teamId?: string;
  slug?: string;
}

/**
 * Retrieves recent active attack data for a project. Use `since` to set the lookback period in days; it defaults to one day when omitted.
 *
 * Retrieve active attack data within the last N days (default: 1 day)
 *
 * @param teamId - The Team identifier to perform the request on behalf of.
 * @param slug - The Team slug to perform the request on behalf of.
 */
export async function getActiveAttackStatus(
  config: ClientConfig,
  { projectId, since, teamId, slug }: GetActiveAttackStatusParams,
  requestOptions?: RequestOptions,
): Promise<
  | { [key: string]: unknown }
  | {
      anomalies: {
        affectedHostMap: {
          [key: string]: {
            anomalyAlerts?: {
              [key: string]: {
                atMinute: string;
                avgRequests: number;
                stddevRequests: number;
                totalRequestsMinute: number;
                zscore: number;
              };
            };
            ddosAlerts?: {
              [key: string]: {
                atMinute: string;
                totalReqs: number;
              };
            };
          };
        };
        atMinute: number;
        endTime: number | null;
        ownerId: string;
        projectId: string;
        startTime: number;
        state?: string;
      }[];
    }
> {
  if (since != null) {
    validateRange("since", since, { min: 1 });
  }

  const _resp = await sdkRequest<
    | { [key: string]: unknown }
    | {
        anomalies: {
          affectedHostMap: {
            [key: string]: {
              anomalyAlerts?: {
                [key: string]: {
                  atMinute: string;
                  avgRequests: number;
                  stddevRequests: number;
                  totalRequestsMinute: number;
                  zscore: number;
                };
              };
              ddosAlerts?: {
                [key: string]: {
                  atMinute: string;
                  totalReqs: number;
                };
              };
            };
          };
          atMinute: number;
          endTime: number | null;
          ownerId: string;
          projectId: string;
          startTime: number;
          state?: string;
        }[];
      }
  >({
    method: "GET",
    path: `/v1/security/firewall/attack-status`,
    operationId: "getActiveAttackStatus",
    responseDecoder: "json",
    ...requestOptions,
    query: {
      projectId: queryValue("projectId", projectId, "form", true),
      since: queryValue("since", since, "form", true),
      teamId: queryValue("teamId", teamId, "form", true),
      slug: queryValue("slug", slug, "form", true),
    },
    config,
  });
  return sdkDecode(_resp, () =>
    decodeResponseEnums(_resp.data, {
      oneOf: [
        { type: "object" },
        {
          type: "object",
          required: ["anomalies"],
          properties: {
            anomalies: {
              type: "array",
              items: {
                type: "object",
                required: [
                  "affectedHostMap",
                  "atMinute",
                  "endTime",
                  "ownerId",
                  "projectId",
                  "startTime",
                ],
                nullableRequired: ["endTime"],
                properties: {
                  affectedHostMap: {
                    type: "object",
                    additionalProperties: {
                      type: "object",
                      properties: {
                        anomalyAlerts: {
                          type: "object",
                          additionalProperties: {
                            type: "object",
                            required: [
                              "at_minute",
                              "avg_requests",
                              "stddev_requests",
                              "total_requests_minute",
                              "zscore",
                            ],
                          },
                        },
                        ddosAlerts: {
                          type: "object",
                          additionalProperties: {
                            type: "object",
                            required: ["atMinute", "totalReqs"],
                          },
                        },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      ],
    }),
  );
}
